class Solution {
public:
    int numRabbits(vector<int>& answers) {
        int count[1000] = {0};
        for (int a : answers) {
            count[a]++;
        }
        int result = 0;
        for (int x = 0; x < 1000; x++) {
            if (count[x] > 0) {
                int groupSize = x + 1;
                int groups = (count[x] + groupSize - 1) / groupSize;
                result += groups * groupSize;
            }
        }
        return result;
    }
};
